INSERT IGNORE INTO community_posts (`id`,`title`,`summary`,`cluster_id`,`cluster_name`,`post_kind`,`author_name`,`trust_score`,`status`,`created_at`,`updated_at`,author_id) SELECT 'demo-v10-discussion-1','[Mẫu] Cần hỏi gì trước khi đi xem phòng?','[Dữ liệu mẫu] Chủ đề minh họa cách đặt câu hỏi về giá thuê, chi phí điện nước và lịch xem phòng. Đây không phải đánh giá của người thuê thật.','hai-chau','Hải Châu','question','[Mẫu] An tìm phòng',0,'verified','2026-11-10 10:18:42','2026-11-10 10:18:42',u.id FROM users u WHERE external_id='demo-v10-1';
INSERT IGNORE INTO community_posts (`id`,`title`,`summary`,`cluster_id`,`cluster_name`,`post_kind`,`author_name`,`trust_score`,`status`,`created_at`,`updated_at`,author_id) SELECT 'demo-v10-discussion-2','[Mẫu] Chuẩn bị thông tin trước khi thuê chung','[Dữ liệu mẫu] Chủ đề minh họa trao đổi nội quy, hợp đồng và nhu cầu ở ghép. Các tài khoản bên dưới là dữ liệu mẫu.','hai-chau','Hải Châu','question','[Mẫu] An tìm phòng',0,'verified','2026-11-10 10:18:42','2026-11-10 10:18:42',u.id FROM users u WHERE external_id='demo-v10-1';
